def _convert_messages_to_google(messages: list[dict]) -> list[dict]:
    """Converte messaggi formato Anthropic (con tool_use/tool_result) in formato Google genai Contents."""
    from google.genai import types  # type: ignore[import]
    import json as _json

    contents: list[Any] = []
    for msg in messages:
        role = msg.get("role", "user")
        # Google usa "user" e "model" (non "assistant")
        g_role = "model" if role == "assistant" else "user"
        content = msg.get("content", "")

        if isinstance(content, str):
            contents.append(types.Content(
                role=g_role,
                parts=[types.Part.from_text(text=content)],
            ))
        elif isinstance(content, list):
            parts: list[Any] = []
            tool_response_parts: list[Any] = []
            for block in content:
                btype = block.get("type")
                if btype == "text":
                    parts.append(types.Part.from_text(text=block.get("text", "")))
                elif btype == "tool_use":
                    # Blocco tool_use (assistant chiede di chiamare un tool)
                    parts.append(types.Part.from_function_call(
                        name=block["name"],
                        args=block.get("input", {}),
                    ))
                elif btype == "tool_result":
                    # Blocco tool_result (risultato della chiamata tool)
                    result_content = block.get("content", "")
                    if isinstance(result_content, list):
                        # Estrai testo dai blocchi
                        result_content = " ".join(
                            b.get("text", "") for b in result_content if b.get("type") == "text"
                        )
                    tool_response_parts.append(types.Part.from_function_response(
                        name=block.get("tool_use_id", "unknown"),
                        response={"result": str(result_content)},
                    ))

            if tool_response_parts:
                # I tool_result vanno come messaggio "user" separato
                contents.append(types.Content(
                    role="user",
                    parts=tool_response_parts,
                ))
            if parts:
                contents.append(types.Content(
                    role=g_role,
                    parts=parts,
                ))
        else:
            contents.append(types.Content(
                role=g_role,
                parts=[types.Part.from_text(text=str(content))],
            ))

    return contents

