def _google_thinking_budget() -> int:
    """Budget di thinking per Gemini 2.5 (DB-driven, regola G).

    Limita i token di reasoning interno per lasciare spazio all'output/function
    call ed evitare il troncamento (MAX_TOKENS / output vuoto). Setting:
    `providers.google.thinking_budget`. Default 8192 (range valido Gemini 2.5:
    128-32768; -1 = dinamico illimitato, sconsigliato con tool).
    """
    try:
        raw = _read_setting("providers.google.thinking_budget", "8192")
        val = int(str(raw).strip())
        # Clamp difensivo al range supportato (esclude il dinamico -1 con tool).
        if val < 128:
            return 128
        if val > 32768:
            return 32768
        return val
    except Exception:
        return 8192


